create extension if not exists pgcrypto;
create table if not exists public.products (id bigint generated by default as identity primary key,name text not null,price numeric(12,2) not null default 0,stock integer not null default 0,category text,image text,description text,created_at timestamptz not null default now());
create table if not exists public.orders (id bigint generated by default as identity primary key,customer_name text not null,phone text not null,address text not null,payment_method text not null default 'cod',total numeric(12,2) not null default 0,status text not null default 'pending' check(status in ('pending','confirmed','preparing','shipped','delivered','cancelled')),created_at timestamptz not null default now());
create table if not exists public.order_items (id bigint generated by default as identity primary key,order_id bigint not null references public.orders(id) on delete cascade,product_id bigint references public.products(id) on delete set null,quantity integer not null default 1,price numeric(12,2) not null default 0);
create table if not exists public.admin_users (user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.support_messages (id bigint generated by default as identity primary key,name text,phone text,message text not null,created_at timestamptz not null default now());

alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.admin_users enable row level security; alter table public.support_messages enable row level security;

drop policy if exists "products public read" on public.products; create policy "products public read" on public.products for select using (true);
drop policy if exists "products admin manage" on public.products; create policy "products admin manage" on public.products for all to authenticated using (exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check (exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
drop policy if exists "orders public insert" on public.orders; create policy "orders public insert" on public.orders for insert with check (true);
drop policy if exists "orders admin read" on public.orders; create policy "orders admin read" on public.orders for select to authenticated using (exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
drop policy if exists "orders admin update" on public.orders; create policy "orders admin update" on public.orders for update to authenticated using (exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check (exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
drop policy if exists "items public insert" on public.order_items; create policy "items public insert" on public.order_items for insert with check (true);
drop policy if exists "items admin read" on public.order_items; create policy "items admin read" on public.order_items for select to authenticated using (exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
drop policy if exists "admin self read" on public.admin_users; create policy "admin self read" on public.admin_users for select to authenticated using (user_id=auth.uid());
drop policy if exists "support public insert" on public.support_messages; create policy "support public insert" on public.support_messages for insert with check (true);
drop policy if exists "support admin read" on public.support_messages; create policy "support admin read" on public.support_messages for select to authenticated using (exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
